def find_rectangular_enclosures(grid):
    """Find rectangular enclosures where one color forms a complete rectangle."""
    background = None
    frame_color = None

    # Find most common colors
    from collections import Counter
    colors = Counter()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            colors[grid[r][c]] += 1

    print(f"Color counts: {colors}")

    # Try each possible frame color vs background
    results = {}
    for frame_c in colors:
        bg_c = None
        for other_c in colors:
            if other_c != frame_c:
                bg_c = other_c
                break

        if bg_c is None:
            continue

        found_rectangles = []

        # Find all potential rectangle corners
        for r1 in range(len(grid)):
            for c1 in range(len(grid[0])):
                if grid[r1][c1] == frame_c:
                    # Look for potential rectangle starting here
                    for h in range(1, min(len(grid), 10)):  # Limit height
                        for w in range(1, min(len(grid[0]), 10)):  # Limit width
                            r2 = r1 + h - 1
                            c2 = c1 + w - 1

                            # Check if all four corners are frame color
                            if (r2 >= len(grid) or c2 >= len(grid[0]) or 
                                grid[r1][c2] != frame_c or 
                                grid[r2][c1] != frame_c or 
                                grid[r2][c2] != frame_c):
                                continue

                            # Check if entire perimeter is frame color
                            perimeter_ok = True
                            # Top and bottom edges
                            for j in range(c1, c2 + 1):
                                if grid[r1][j] != frame_c or grid[r2][j] != frame_c:
                                    perimeter_ok = False
                                    break
                            if not perimeter_ok:
                                continue
                            # Left and right edges
                            for i in range(r1 + 1, r2):
                                if grid[i][c1] != frame_c or grid[i][c2] != frame_c:
                                    perimeter_ok = False
                                    break
                            if not perimeter_ok:
                                continue

                            # Check if interior is all background color
                            interior_all_bg = True
                            for i in range(r1 + 1, r2):
                                for j in range(c1 + 1, c2):
                                    if grid[i][j] != bg_c:
                                        interior_all_bg = False
                                        break
                                if not interior_all_bg:
                                    break

                            if interior_all_bg:
                                found_rectangles.append(((r1, c1), (r2, c2)))

        if found_rectangles:
            results[(frame_c, bg_c)] = found_rectangles

    return results

